export function enrichPlayer(player, index = 0) {
  const ratingCount =
    Number.isFinite(player.ratingCount) && player.ratingCount >= 0
      ? player.ratingCount
      : 8 + ((index * 5 + Number(player.number || 0)) % 13);
  return {
    ...player,
    ratingCount,
    userRating: player.userRating ?? null,
  };
}

initialState.teams = initialState.teams.map((team) => ({
  ...team,
  players: team.players.map(enrichPlayer),
}));
